insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (1, 1, null, 'a', 'Welcome to Lumen & Co', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We design and build lighting for shops, hotels and museums, from our workshop in Lyon. There are 34 of us: designers, engineers, a sales team and an office team who keep everything running."}]},{"type":"paragraph","content":[{"type":"text","text":"This handbook is where we write down how things work, so that nobody has to ask twice. If something here is wrong or missing, fix it — every editor can."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"How we work"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We say what we will do, then do it.","marks":[{"type":"bold"}]},{"type":"text","text":" A promise to a client is a promise from all of us."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We write things down.","marks":[{"type":"bold"}]},{"type":"text","text":" Decisions go in the wiki, not in someone’s head."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We ask early.","marks":[{"type":"bold"}]},{"type":"text","text":" A question on Monday saves a mistake on Friday."}]}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Your first week"}]},{"type":"taskList","content":[{"type":"taskItem","attrs":{"checked":true},"content":[{"type":"paragraph","content":[{"type":"text","text":"Pick up your laptop and badge from Sofia (office manager)"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Read "},{"type":"pageRef","attrs":{"id":"2"}},{"type":"text","text":" and "},{"type":"pageRef","attrs":{"id":"3"}}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Set up your accounts: see "},{"type":"pageRef","attrs":{"id":"4"}}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Have lunch with your team — the company pays"}]}]}]},{"type":"callout","attrs":{"tone":"tip"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Can’t find something? Use the search box at the top: it reads every page, in English and in French."}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Useful pages"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"For"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Read"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Time off"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pageRef","attrs":{"id":"2"}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Spending money"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pageRef","attrs":{"id":"3"}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Laptop, Wi-Fi"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pageRef","attrs":{"id":"4"}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Anything else"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pageRef","attrs":{"id":"7"}}]}]}]}]}]}'::jsonb, 'We design and build lighting for shops, hotels and museums, from our workshop in Lyon. There are 34 of us: designers, engineers, a sales team and an office team who keep everything running.
This handbook is where we write down how things work, so that nobody has to ask twice. If something here is wrong or missing, fix it — every editor can.
How we work
We say what we will do, then do it. A promise to a client is a promise from all of us.
We write things down. Decisions go in the wiki, not in someone’s head.
We ask early. A question on Monday saves a mistake on Friday.
Your first week
Pick up your laptop and badge from Sofia (office manager)
Read Holidays and time off and Expense policy
Set up your accounts: see IT setup
Have lunch with your team — the company pays
Can’t find something? Use the search box at the top: it reads every page, in English and in French.
Useful pages
For │ Read
Time off │ Holidays and time off
Spending money │ Expense policy
Laptop, Wi-Fi │ IT setup
Anything else │ Who to ask', 1, 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '120 days', 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '6 days' - interval '37 minutes');
