insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (2, 1, null, 'b', 'Holidays and time off', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Everyone gets "},{"type":"text","text":"25 working days","marks":[{"type":"bold"}]},{"type":"text","text":" of paid holiday a year, plus public holidays and "},{"type":"text","text":"2 extra days","marks":[{"type":"bold"}]},{"type":"text","text":" between Christmas and New Year, when the workshop closes."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"How to ask"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ask your manager at least "},{"type":"text","text":"two weeks","marks":[{"type":"bold"}]},{"type":"text","text":" ahead — a month for more than a week off."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once they agree, add it to the team calendar so that everyone knows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Before you leave, set an out-of-office reply that names who covers for you."}]}]}]},{"type":"callout","attrs":{"tone":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Holidays run from 1 June to 31 May. Days not taken by 31 May are lost, unless your manager agreed in writing to carry them over."}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Other leave"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Kind"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Days"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Tell us"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Your wedding or civil partnership"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"4"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"1 month ahead"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Birth or adoption (second parent)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"3 + 25"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"as soon as you can"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Moving house"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"1 week ahead"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Death of a close relative"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"3"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"as soon as you can"}]}]}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Sick days"}]},{"type":"paragraph","content":[{"type":"text","text":"Tell your manager "},{"type":"text","text":"before 10:00","marks":[{"type":"bold"}]},{"type":"text","text":", and send the doctor’s note to Sofia within 48 hours. Get well: nobody expects you to answer emails."}]},{"type":"paragraph","content":[{"type":"text","text":"Questions? See "},{"type":"pageRef","attrs":{"id":"7"}},{"type":"text","text":"."}]}]}'::jsonb, 'Everyone gets 25 working days of paid holiday a year, plus public holidays and 2 extra days between Christmas and New Year, when the workshop closes.
How to ask
Ask your manager at least two weeks ahead — a month for more than a week off.
Once they agree, add it to the team calendar so that everyone knows.
Before you leave, set an out-of-office reply that names who covers for you.
Holidays run from 1 June to 31 May. Days not taken by 31 May are lost, unless your manager agreed in writing to carry them over.
Other leave
Kind │ Days │ Tell us
Your wedding or civil partnership │ 4 │ 1 month ahead
Birth or adoption (second parent) │ 3 + 25 │ as soon as you can
Moving house │ 1 │ 1 week ahead
Death of a close relative │ 3 │ as soon as you can
Sick days
Tell your manager before 10:00, and send the doctor’s note to Sofia within 48 hours. Get well: nobody expects you to answer emails.
Questions? See Who to ask.', 2, 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '90 days', 'mbr_inesaaaaaaaaaaaaaaaaaaaaaa', now() - interval '2 days' - interval '74 minutes');
