insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (3, 1, null, 'c', 'Expense policy', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We pay back what you spend for work, within a month. The rules are few, and the same for everyone."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"The rules"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep "},{"type":"text","text":"every receipt","marks":[{"type":"bold"}]},{"type":"text","text":". A photo from your phone is fine."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Travel by "},{"type":"text","text":"train","marks":[{"type":"bold"}]},{"type":"text","text":" when the trip takes under four hours; book second class."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hotels: up to "},{"type":"text","text":"130 €","marks":[{"type":"bold"}]},{"type":"text","text":" a night in Paris, "},{"type":"text","text":"100 €","marks":[{"type":"bold"}]},{"type":"text","text":" elsewhere."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Meals with clients: up to "},{"type":"text","text":"40 €","marks":[{"type":"bold"}]},{"type":"text","text":" per person, drinks included."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Taxis only late at night or with heavy samples."}]}]}]},{"type":"callout","attrs":{"tone":"warning"},"content":[{"type":"paragraph","content":[{"type":"text","text":"No receipt, no refund. The accountants cannot make exceptions — the tax office does not either."}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"How to claim"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Send your receipts to the Expenses tool before the 25th of the month."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your manager approves them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The money arrives with your next payslip."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"For a large purchase (over 500 €), ask your manager "},{"type":"text","text":"before","marks":[{"type":"bold"}]},{"type":"text","text":" you buy."}]}]}'::jsonb, 'We pay back what you spend for work, within a month. The rules are few, and the same for everyone.
The rules
Keep every receipt. A photo from your phone is fine.
Travel by train when the trip takes under four hours; book second class.
Hotels: up to 130 € a night in Paris, 100 € elsewhere.
Meals with clients: up to 40 € per person, drinks included.
Taxis only late at night or with heavy samples.
No receipt, no refund. The accountants cannot make exceptions — the tax office does not either.
How to claim
Send your receipts to the Expenses tool before the 25th of the month.
Your manager approves them.
The money arrives with your next payslip.
For a large purchase (over 500 €), ask your manager before you buy.', 2, 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '110 days', 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '14 days' - interval '111 minutes');
