insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (8, 1, null, 'f', 'Règlement intérieur', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ce règlement s’applique à toutes les personnes qui travaillent chez Lumen & Co, dans nos locaux comme chez nos clients. Il est aussi affiché dans la cuisine, à côté du tableau d’informations."}]},{"type":"callout","attrs":{"tone":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ce texte a été soumis au CSE, déposé au conseil de prud’hommes de Lyon et transmis à l’inspection du travail. Le publier dans le wiki ne remplace pas ces formalités."}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Horaires"}]},{"type":"paragraph","content":[{"type":"text","text":"Les horaires de référence sont "},{"type":"text","text":"9 h – 17 h 30","marks":[{"type":"bold"}]},{"type":"text","text":", avec une pause déjeuner d’une heure. Chaque équipe peut les adapter avec l’accord de son manager."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Hygiène et sécurité"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Les consignes de l’atelier doivent être respectées : lunettes et gants pour la découpe, chaussures de sécurité pour les livraisons."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Il est interdit de fumer ou de vapoter dans les locaux."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tout accident, même léger, est signalé le jour même à Camille."}]}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Utilisation du matériel"}]},{"type":"paragraph","content":[{"type":"text","text":"Le matériel de l’entreprise sert au travail. Un usage personnel raisonnable de l’ordinateur et du téléphone est toléré."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Sanctions"}]},{"type":"paragraph","content":[{"type":"text","text":"Selon la gravité des faits : observation écrite, avertissement, mise à pied disciplinaire, licenciement. Aucune sanction n’est prise sans que la personne ait été entendue."}]}]}'::jsonb, 'Ce règlement s’applique à toutes les personnes qui travaillent chez Lumen & Co, dans nos locaux comme chez nos clients. Il est aussi affiché dans la cuisine, à côté du tableau d’informations.
Ce texte a été soumis au CSE, déposé au conseil de prud’hommes de Lyon et transmis à l’inspection du travail. Le publier dans le wiki ne remplace pas ces formalités.
Horaires
Les horaires de référence sont 9 h – 17 h 30, avec une pause déjeuner d’une heure. Chaque équipe peut les adapter avec l’accord de son manager.
Hygiène et sécurité
Les consignes de l’atelier doivent être respectées : lunettes et gants pour la découpe, chaussures de sécurité pour les livraisons.
Il est interdit de fumer ou de vapoter dans les locaux.
Tout accident, même léger, est signalé le jour même à Camille.
Utilisation du matériel
Le matériel de l’entreprise sert au travail. Un usage personnel raisonnable de l’ordinateur et du téléphone est toléré.
Sanctions
Selon la gravité des faits : observation écrite, avertissement, mise à pied disciplinaire, licenciement. Aucune sanction n’est prise sans que la personne ait été entendue.', 1, 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '200 days', 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '45 days' - interval '296 minutes');
insert into page_versions (page_id, number, title, doc, body, author, created_at, kind) values (8, 1, 'Règlement intérieur', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ce règlement s’applique à toutes les personnes qui travaillent chez Lumen & Co, dans nos locaux comme chez nos clients. Il est aussi affiché dans la cuisine, à côté du tableau d’informations."}]},{"type":"callout","attrs":{"tone":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ce texte a été soumis au CSE, déposé au conseil de prud’hommes de Lyon et transmis à l’inspection du travail. Le publier dans le wiki ne remplace pas ces formalités."}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Horaires"}]},{"type":"paragraph","content":[{"type":"text","text":"Les horaires de référence sont "},{"type":"text","text":"9 h – 17 h 30","marks":[{"type":"bold"}]},{"type":"text","text":", avec une pause déjeuner d’une heure. Chaque équipe peut les adapter avec l’accord de son manager."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Hygiène et sécurité"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Les consignes de l’atelier doivent être respectées : lunettes et gants pour la découpe, chaussures de sécurité pour les livraisons."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Il est interdit de fumer ou de vapoter dans les locaux."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tout accident, même léger, est signalé le jour même à Camille."}]}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Utilisation du matériel"}]},{"type":"paragraph","content":[{"type":"text","text":"Le matériel de l’entreprise sert au travail. Un usage personnel raisonnable de l’ordinateur et du téléphone est toléré."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Sanctions"}]},{"type":"paragraph","content":[{"type":"text","text":"Selon la gravité des faits : observation écrite, avertissement, mise à pied disciplinaire, licenciement. Aucune sanction n’est prise sans que la personne ait été entendue."}]}]}'::jsonb, 'Ce règlement s’applique à toutes les personnes qui travaillent chez Lumen & Co, dans nos locaux comme chez nos clients. Il est aussi affiché dans la cuisine, à côté du tableau d’informations.
Ce texte a été soumis au CSE, déposé au conseil de prud’hommes de Lyon et transmis à l’inspection du travail. Le publier dans le wiki ne remplace pas ces formalités.
Horaires
Les horaires de référence sont 9 h – 17 h 30, avec une pause déjeuner d’une heure. Chaque équipe peut les adapter avec l’accord de son manager.
Hygiène et sécurité
Les consignes de l’atelier doivent être respectées : lunettes et gants pour la découpe, chaussures de sécurité pour les livraisons.
Il est interdit de fumer ou de vapoter dans les locaux.
Tout accident, même léger, est signalé le jour même à Camille.
Utilisation du matériel
Le matériel de l’entreprise sert au travail. Un usage personnel raisonnable de l’ordinateur et du téléphone est toléré.
Sanctions
Selon la gravité des faits : observation écrite, avertissement, mise à pied disciplinaire, licenciement. Aucune sanction n’est prise sans que la personne ait été entendue.', 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '45 days' - interval '296 minutes', 'created');

insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (9, 1, null, 'g', 'Charte télétravail', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Chacun peut travailler de chez soi "},{"type":"text","text":"jusqu’à deux jours par semaine","marks":[{"type":"bold"}]},{"type":"text","text":", en accord avec son équipe. L’atelier et l’accueil ont leurs propres règles."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Comment ça marche"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Indiquez vos jours de télétravail dans le calendrier de l’équipe le vendredi précédent."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Restez joignable pendant les horaires de référence."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Le mardi est un jour de présence pour tout le monde : c’est le jour de la réunion d’équipe."}]}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Ce que l’entreprise prend en charge"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Un écran et un clavier pour la maison, à demander à Tom."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Une indemnité de "},{"type":"text","text":"2,60 €","marks":[{"type":"bold"}]},{"type":"text","text":" par jour de télétravail, versée avec le salaire."}]}]}]},{"type":"callout","attrs":{"tone":"tip"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Un doute sur votre installation ? La page "},{"type":"pageRef","attrs":{"id":"4"}},{"type":"text","text":" explique comment vous connecter depuis chez vous."}]}]}]}'::jsonb, 'Chacun peut travailler de chez soi jusqu’à deux jours par semaine, en accord avec son équipe. L’atelier et l’accueil ont leurs propres règles.
Comment ça marche
Indiquez vos jours de télétravail dans le calendrier de l’équipe le vendredi précédent.
Restez joignable pendant les horaires de référence.
Le mardi est un jour de présence pour tout le monde : c’est le jour de la réunion d’équipe.
Ce que l’entreprise prend en charge
Un écran et un clavier pour la maison, à demander à Tom.
Une indemnité de 2,60 € par jour de télétravail, versée avec le salaire.
Un doute sur votre installation ? La page IT setup explique comment vous connecter depuis chez vous.', 1, 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '80 days', 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '11 days' - interval '333 minutes');
insert into page_versions (page_id, number, title, doc, body, author, created_at, kind) values (9, 1, 'Charte télétravail', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Chacun peut travailler de chez soi "},{"type":"text","text":"jusqu’à deux jours par semaine","marks":[{"type":"bold"}]},{"type":"text","text":", en accord avec son équipe. L’atelier et l’accueil ont leurs propres règles."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Comment ça marche"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Indiquez vos jours de télétravail dans le calendrier de l’équipe le vendredi précédent."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Restez joignable pendant les horaires de référence."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Le mardi est un jour de présence pour tout le monde : c’est le jour de la réunion d’équipe."}]}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Ce que l’entreprise prend en charge"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Un écran et un clavier pour la maison, à demander à Tom."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Une indemnité de "},{"type":"text","text":"2,60 €","marks":[{"type":"bold"}]},{"type":"text","text":" par jour de télétravail, versée avec le salaire."}]}]}]},{"type":"callout","attrs":{"tone":"tip"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Un doute sur votre installation ? La page "},{"type":"pageRef","attrs":{"id":"4"}},{"type":"text","text":" explique comment vous connecter depuis chez vous."}]}]}]}'::jsonb, 'Chacun peut travailler de chez soi jusqu’à deux jours par semaine, en accord avec son équipe. L’atelier et l’accueil ont leurs propres règles.
Comment ça marche
Indiquez vos jours de télétravail dans le calendrier de l’équipe le vendredi précédent.
Restez joignable pendant les horaires de référence.
Le mardi est un jour de présence pour tout le monde : c’est le jour de la réunion d’équipe.
Ce que l’entreprise prend en charge
Un écran et un clavier pour la maison, à demander à Tom.
Une indemnité de 2,60 € par jour de télétravail, versée avec le salaire.
Un doute sur votre installation ? La page IT setup explique comment vous connecter depuis chez vous.', 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '11 days' - interval '333 minutes', 'created');

insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (10, 2, null, 'a', 'Sales playbook', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How we win and keep clients. Short on purpose: read it before your first client meeting."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Who we sell to"}]},{"type":"paragraph","content":[{"type":"text","text":"Shop chains, hotel groups and museums who care how a space "},{"type":"text","text":"feels","marks":[{"type":"bold"}]},{"type":"text","text":". Not the cheapest lighting — the lighting that makes people stay."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"The five steps"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"First call","marks":[{"type":"bold"}]},{"type":"text","text":" — understand the place and the deadline. Book a visit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Visit","marks":[{"type":"bold"}]},{"type":"text","text":" — photos, measurements, the light at different hours."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Proposal","marks":[{"type":"bold"}]},{"type":"text","text":" — a mood board and a first price range within a week. See "},{"type":"pageRef","attrs":{"id":"11"}},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Quote","marks":[{"type":"bold"}]},{"type":"text","text":" — detailed, valid 30 days, signed by Inès."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Handover","marks":[{"type":"bold"}]},{"type":"text","text":" — the project goes to the design team, with the visit notes."}]}]}]},{"type":"callout","attrs":{"tone":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Every client gets a reply within one working day, even if it is only “we are on it”."}]}]},{"type":"paragraph","content":[{"type":"text","text":"Preparing a meeting in French? See "},{"type":"pageRef","attrs":{"id":"12"}},{"type":"text","text":"."}]}]}'::jsonb, 'How we win and keep clients. Short on purpose: read it before your first client meeting.
Who we sell to
Shop chains, hotel groups and museums who care how a space feels. Not the cheapest lighting — the lighting that makes people stay.
The five steps
First call — understand the place and the deadline. Book a visit.
Visit — photos, measurements, the light at different hours.
Proposal — a mood board and a first price range within a week. See Pricing 2026.
Quote — detailed, valid 30 days, signed by Inès.
Handover — the project goes to the design team, with the visit notes.
Every client gets a reply within one working day, even if it is only “we are on it”.
Preparing a meeting in French? See Préparer un rendez-vous client.', 1, 'mbr_inesaaaaaaaaaaaaaaaaaaaaaa', now() - interval '70 days', 'mbr_inesaaaaaaaaaaaaaaaaaaaaaa', now() - interval '3 days' - interval '370 minutes');
