insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (13, 3, null, 'a', 'Onboarding for engineers', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Welcome to the tech team. Your first week is about learning how our fixtures are controlled, not shipping."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Day one"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Get your accounts: see "},{"type":"pageRef","attrs":{"id":"4"}},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clone the controller firmware and the configuration tool."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pair with Léa on a small fix."}]}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"How we ship"}]},{"type":"paragraph","content":[{"type":"text","text":"Every change is reviewed by one other person. We ship on Tuesdays and Thursdays, never on Fridays. See "},{"type":"pageRef","attrs":{"id":"14"}},{"type":"text","text":"."}]},{"type":"codeBlock","content":[{"type":"text","text":"make test && make firmware"}]}]}'::jsonb, 'Welcome to the tech team. Your first week is about learning how our fixtures are controlled, not shipping.
Day one
Get your accounts: see IT setup.
Clone the controller firmware and the configuration tool.
Pair with Léa on a small fix.
How we ship
Every change is reviewed by one other person. We ship on Tuesdays and Thursdays, never on Fridays. See Deploying a firmware update.
make test && make firmware', 1, 'mbr_tomaaaaaaaaaaaaaaaaaaaaaaa', now() - interval '65 days', 'mbr_tomaaaaaaaaaaaaaaaaaaaaaaa', now() - interval '5 days' - interval '481 minutes');
insert into page_versions (page_id, number, title, doc, body, author, created_at, kind) values (13, 1, 'Onboarding for engineers', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Welcome to the tech team. Your first week is about learning how our fixtures are controlled, not shipping."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Day one"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Get your accounts: see "},{"type":"pageRef","attrs":{"id":"4"}},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clone the controller firmware and the configuration tool."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pair with Léa on a small fix."}]}]}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"How we ship"}]},{"type":"paragraph","content":[{"type":"text","text":"Every change is reviewed by one other person. We ship on Tuesdays and Thursdays, never on Fridays. See "},{"type":"pageRef","attrs":{"id":"14"}},{"type":"text","text":"."}]},{"type":"codeBlock","content":[{"type":"text","text":"make test && make firmware"}]}]}'::jsonb, 'Welcome to the tech team. Your first week is about learning how our fixtures are controlled, not shipping.
Day one
Get your accounts: see IT setup.
Clone the controller firmware and the configuration tool.
Pair with Léa on a small fix.
How we ship
Every change is reviewed by one other person. We ship on Tuesdays and Thursdays, never on Fridays. See Deploying a firmware update.
make test && make firmware', 'mbr_tomaaaaaaaaaaaaaaaaaaaaaaa', now() - interval '5 days' - interval '481 minutes', 'created');

insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (15, 3, null, 'b', 'When something breaks', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A site is dark, or a controller does not answer. Stay calm and follow the list."}]},{"type":"taskList","content":[{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Call the client back within 30 minutes, even without news"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Check the site’s controller from the configuration tool"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Roll back the last update if it went out in the last 48 hours"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Write what happened in the incident log, with the times"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Tell Camille if the client’s opening hours are affected"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"After it is fixed, we meet for 20 minutes to understand why — never to blame."}]}]}'::jsonb, 'A site is dark, or a controller does not answer. Stay calm and follow the list.
Call the client back within 30 minutes, even without news
Check the site’s controller from the configuration tool
Roll back the last update if it went out in the last 48 hours
Write what happened in the incident log, with the times
Tell Camille if the client’s opening hours are affected
After it is fixed, we meet for 20 minutes to understand why — never to blame.', 1, 'mbr_tomaaaaaaaaaaaaaaaaaaaaaaa', now() - interval '45 days', 'mbr_tomaaaaaaaaaaaaaaaaaaaaaaa', now() - interval '45 days' - interval '555 minutes');
