insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (16, 4, null, 'a', 'Salary review', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Salaries are reviewed once a year, in March, for everyone who has been with us for six months or more."}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Managers send their proposals by 15 February."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Camille and the founders compare them across teams."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everyone hears their new salary in a one-to-one before 31 March."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The budget and the salary bands are in the finance folder, not here."}]}]}'::jsonb, 'Salaries are reviewed once a year, in March, for everyone who has been with us for six months or more.
Managers send their proposals by 15 February.
Camille and the founders compare them across teams.
Everyone hears their new salary in a one-to-one before 31 March.
The budget and the salary bands are in the finance folder, not here.', 1, 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '150 days', 'mbr_camilleaaaaaaaaaaaaaaaaaaa', now() - interval '40 days' - interval '592 minutes');
