insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (17, 4, null, 'b', 'Entretiens annuels', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Chaque personne a un entretien annuel avec son manager en janvier, et un entretien professionnel tous les deux ans."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Préparer l’entretien"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Relire les objectifs de l’année passée."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Noter deux réussites et une difficulté."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Penser à une formation qui vous aiderait."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Le compte rendu est signé par les deux personnes, et chacune en garde une copie."}]}]}'::jsonb, 'Chaque personne a un entretien annuel avec son manager en janvier, et un entretien professionnel tous les deux ans.
Préparer l’entretien
Relire les objectifs de l’année passée.
Noter deux réussites et une difficulté.
