insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (6, 1, 4, 'b', 'Password manager', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We keep every shared password in the team''s password manager, never in a spreadsheet or a message."}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accept the invitation Tom sends you on your first day."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose a long master password: four random words work well."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Turn on two-step sign-in with your phone."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Lost your master password? Tom can reset your access, but not recover what was only in your personal vault."}]}]}'::jsonb, 'We keep every shared password in the team''s password manager, never in a spreadsheet or a message.
Accept the invitation Tom sends you on your first day.
Choose a long master password: four random words work well.
Turn on two-step sign-in with your phone.
Lost your master password? Tom can reset your access, but not recover what was only in your personal vault.', 1, 'mbr_tomaaaaaaaaaaaaaaaaaaaaaaa', now() - interval '60 days', 'mbr_tomaaaaaaaaaaaaaaaaaaaaaaa', now() - interval '60 days' - interval '222 minutes');
