insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (12, 2, 10, 'a', 'Préparer un rendez-vous client', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Avant chaque rendez-vous, prenez dix minutes pour cette liste."}]},{"type":"taskList","content":[{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Relire les échanges précédents et la dernière proposition"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Vérifier qui sera présent, et leur rôle"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Préparer trois références proches de leur projet"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Emporter le nuancier et deux échantillons"}]}]},{"type":"taskItem","attrs":{"checked":false},"content":[{"type":"paragraph","content":[{"type":"text","text":"Noter la question qu’on n’a pas encore posée"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Après le rendez-vous, envoyez un compte rendu "},{"type":"text","text":"le jour même","marks":[{"type":"bold"}]},{"type":"text","text":" : ce qui a été dit, ce qui a été décidé, la prochaine étape."}]}]}'::jsonb, 'Avant chaque rendez-vous, prenez dix minutes pour cette liste.
