insert into pages (id, space_id, parent_id, position, title, doc, body, version, created_by, created_at, updated_by, updated_at) overriding system value values (14, 3, 13, 'a', 'Deploying a firmware update', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Updates go to client sites in three waves, so that a mistake reaches few fixtures."}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Workshop","marks":[{"type":"bold"}]},{"type":"text","text":" — the test wall in the workshop, for one day."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pilot sites","marks":[{"type":"bold"}]},{"type":"text","text":" — our office and two friendly clients, for three days."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everyone","marks":[{"type":"bold"}]},{"type":"text","text":" — the rest, over a week, at night."}]}]}]},{"type":"callout","attrs":{"tone":"warning"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Never update a museum during opening hours, even if the change looks harmless."}]}]},{"type":"paragraph","content":[{"type":"text","text":"If anything goes wrong, follow "},{"type":"pageRef","attrs":{"id":"15"}},{"type":"text","text":"."}]}]}'::jsonb, 'Updates go to client sites in three waves, so that a mistake reaches few fixtures.
Workshop — the test wall in the workshop, for one day.
Pilot sites — our office and two friendly clients, for three days.
Everyone — the rest, over a week, at night.
Never update a museum during opening hours, even if the change looks harmless.
If anything goes wrong, follow When something breaks.', 1, 'mbr_leaaaaaaaaaaaaaaaaaaaaaaaa', now() - interval '55 days', 'mbr_leaaaaaaaaaaaaaaaaaaaaaaaa', now() - interval '8 days' - interval '518 minutes');
insert into page_versions (page_id, number, title, doc, body, author, created_at, kind) values (14, 1, 'Deploying a firmware update', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Updates go to client sites in three waves, so that a mistake reaches few fixtures."}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Workshop","marks":[{"type":"bold"}]},{"type":"text","text":" — the test wall in the workshop, for one day."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pilot sites","marks":[{"type":"bold"}]},{"type":"text","text":" — our office and two friendly clients, for three days."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everyone","marks":[{"type":"bold"}]},{"type":"text","text":" — the rest, over a week, at night."}]}]}]},{"type":"callout","attrs":{"tone":"warning"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Never update a museum during opening hours, even if the change looks harmless."}]}]},{"type":"paragraph","content":[{"type":"text","text":"If anything goes wrong, follow "},{"type":"pageRef","attrs":{"id":"15"}},{"type":"text","text":"."}]}]}'::jsonb, 'Updates go to client sites in three waves, so that a mistake reaches few fixtures.
